public List<MessaggioDTO> getMessaggiRichiesta(long richiestaId, long siteGroupId, boolean visibile, Integer start, Integer end, boolean paginazione, Long userId) {

    List<CommentoRichiesta> commentiRichiesta = commentoRichiestaLocalService.getCommentiRichiestaByRichiestaIdVisibile(richiestaId, visibile, QueryUtil.ALL_POS, QueryUtil.ALL_POS);
    // List<AttivitaRichiesta> attivitaRichiesta =
    // attivitaRichiestaLocalService.getAttivitaRichiestaByRichiestaId(richiestaId,
    // QueryUtil.ALL_POS, QueryUtil.ALL_POS);
    List<Comunicazione> comunicazioniRichiesta = comunicazioneLocalService.getByRichiestaId(richiestaId, QueryUtil.ALL_POS, QueryUtil.ALL_POS, null);

    Organization organization = null;
    if (siteGroupId > 0) {
        try {
            organization = organizationUtility.getSiteOrganization(siteGroupId);
        }
        catch (PortalException portalException) {
            log.error("Impossibile recuperare l'organizzazione. :: " + portalException.getMessage(), portalException);
        }
    }

    List<MessaggioDTO> listaFinale = new ArrayList<>();
    List<MessaggioDTO> result = new ArrayList<>();
    listaFinale.addAll(messaggioAdapterUtil.adapt(commentiRichiesta, organization, userId));
    // result.addAll(messaggioAdapterUtil.adapt(attivitaRichiesta));
    listaFinale.addAll(messaggioAdapterUtil.adapt(comunicazioniRichiesta, organization, userId));

    listaFinale.removeAll(Collections.singleton(null));


    if (paginazione) {
        if (start != null && end != null) {
            if (end > listaFinale.size()) {
                end = listaFinale.size();
            }

            result = listaFinale.subList(start, end);
        }
    } else {
        result = listaFinale;
    }
    result.sort(Comparator.comparing(MessaggioDTO::getCreateDate, Comparator.nullsFirst(Comparator.naturalOrder())).reversed());

    return result;
}

