1	package it.servizidigitali.gestionebandi.service.persistence.impl;
2	
3	import java.util.List;
4	
5	import org.osgi.service.component.annotations.Component;
6	
7	import com.liferay.portal.kernel.dao.orm.DynamicQuery;
8	import com.liferay.portal.kernel.dao.orm.DynamicQueryFactoryUtil;
9	import com.liferay.portal.kernel.dao.orm.PropertyFactoryUtil;
10	import com.liferay.portal.kernel.dao.orm.RestrictionsFactoryUtil;
11	import com.liferay.portal.kernel.util.Validator;
12	
13	import it.servizidigitali.gestionebandi.model.CommentoDomandaBando;
14	import it.servizidigitali.gestionebandi.service.CommentoDomandaBandoLocalServiceUtil;
15	import it.servizidigitali.gestionebandi.service.DomandaBandoLocalServiceUtil;
16	import it.servizidigitali.gestionebandi.service.LetturaCommentoDomandaBandoLocalServiceUtil;
17	import it.servizidigitali.gestionebandi.service.persistence.CommentoDomandaBandoFinder;
18	
19	@Component(service = CommentoDomandaBandoFinder.class)
20	public class CommentoDomandaBandoFinderImpl extends CommentoDomandaBandoFinderBaseImpl implements CommentoDomandaBandoFinder {
21	
22	    @Override
23	    public List<CommentoDomandaBando> findCommentiByCodiceFiscaleAndVisibileAndCompanyId(String codiceFiscale, long companyId) {
24	
25	        ClassLoader classLoader = getClass().getClassLoader();
26	
27	        DynamicQuery dynamicQuery = DynamicQueryFactoryUtil.forClass(CommentoDomandaBando.class, classLoader);
28	        DynamicQuery domandaBandoDynamicQuery = DomandaBandoLocalServiceUtil.dynamicQuery();
29	
30	        if (Validator.isNotNull(codiceFiscale)) {
31	            domandaBandoDynamicQuery.add(RestrictionsFactoryUtil.eq("codiceFiscale", codiceFiscale));
32	            domandaBandoDynamicQuery.setProjection(PropertyFactoryUtil.forName("domandaBandoId"));
33	            dynamicQuery.add(PropertyFactoryUtil.forName("domandaBandoId").in(domandaBandoDynamicQuery));
34	            dynamicQuery.add(PropertyFactoryUtil.forName("visibile").eq(true));
35	            if (companyId > 0) {
36	                dynamicQuery.add(RestrictionsFactoryUtil.eq("companyId", companyId));
37	            }
38	        }
39	
40	        return commentoDomandaBandoPersistence.findWithDynamicQuery(dynamicQuery);
41	    }
42	
43	    @Override
44	    public long countCommentiNonLettiByDomandaBandoIdAndUserId(long domandaBandoId, long userId) {
45	        DynamicQuery commentiQuery = createCommentiNonLettiDynamicQuery(domandaBandoId, userId);
46	
47	        return commentoDomandaBandoPersistence.countWithDynamicQuery(commentiQuery);
48	    }
49	
50	    @Override
51	    public List<Long> findCommentIdsNonLettiByDomandaBandoIdAndUserId(long domandaBandoId, long userId) {
52	        DynamicQuery commentiQuery = createCommentiNonLettiDynamicQuery(domandaBandoId, userId);
53	
54	        commentiQuery.setProjection(PropertyFactoryUtil.forName("commentoDomandaBandoId"));
55	
56	        return commentoDomandaBandoPersistence.findWithDynamicQuery(commentiQuery);
57	    }
58	
59	    private DynamicQuery createCommentiNonLettiDynamicQuery(long domandaBandoId, long userId) {
60	        DynamicQuery lettureSubQuery = LetturaCommentoDomandaBandoLocalServiceUtil.dynamicQuery();
61	
62	        lettureSubQuery.add(
63	                RestrictionsFactoryUtil.eq("primaryKey.userId", userId));
64	        lettureSubQuery.setProjection(
65	                PropertyFactoryUtil.forName("primaryKey.commentoDomandaBandoId"));
66	
67	        DynamicQuery commentiQuery = CommentoDomandaBandoLocalServiceUtil.dynamicQuery();
68	
69	        commentiQuery.add(
70	                RestrictionsFactoryUtil.eq("domandaBandoId", domandaBandoId));
71	        commentiQuery.add(
72	                RestrictionsFactoryUtil.ne("userId", userId));
73	        commentiQuery.add(
74	                PropertyFactoryUtil.forName("commentoDomandaBandoId")
75	                        .notIn(lettureSubQuery));
76	
77	        return commentiQuery;
78	    }
79	}
