@Override
public synchronized String getToken(long groupId, AmbienteRiferimento ambiente, Contesto contesto) {
    //TODO rimuovere quanto prima
    if (Validator.isNull(contesto)) {
        contesto = Contesto.HUB_PROCEDIMENTI;
    }

    String token = null;

    try{
        ApiPugliaEnteConfiguration configuration = configurationProvider.getGroupConfiguration(ApiPugliaEnteConfiguration.class, groupId);

        String tokenKey = String.format("token_%s_%s", contesto.name(), ambiente.name());
        token = apiPugliaCacheService.get(tokenKey);

        if(Validator.isNull(token)){
            WebClient client = getClient(configuration.baseUrl() + configuration.tokenPath());
            client.query("grant_type", "client_credentials");

            String consumerKey = getConsumerKey(configuration, ambiente, contesto);
            String secretKey = getSecretKey(configuration, ambiente, contesto);

            String credentials = consumerKey + ":" + secretKey;

            String basic = Base64.getEncoder().encodeToString(credentials.getBytes());
            String authorization = "Basic " + basic;
            client.header("Authorization", authorization);
            MultivaluedMap<String,String> map = new MultivaluedHashMap<String,String>();

            String response = client.post(Entity.form(map), String.class);
            token = toToken(response);

            apiPugliaCacheService.put(tokenKey, token);
        }
    }catch(Exception e){
        log.error("getTokenApiPuglia :: tokenKey: " + String.format("token_%s_%s", contesto.name(), ambiente.name())
                + " groupId: " + groupId + " - " + e.getMessage(), e);
    }

    if(Validator.isNull(token)){
        log.warn("getTokenApiPuglia :: token NULL o vuoto per groupId: " + groupId
                + " contesto: " + contesto + " ambiente: " + ambiente);
    }

    return token;
}

@Override
public void invalidateToken(long groupId, AmbienteRiferimento ambiente, Contesto contesto) {
    String tokenKey = String.format("token_%s_%s", contesto.name(), ambiente.name());
    apiPugliaCacheService.remove(tokenKey);
    log.info("invalidateToken :: rimosso token dalla cache per key: " + tokenKey);
}

private String getSecretKey(ApiPugliaEnteConfiguration configuration, AmbienteRiferimento ambiente, Contesto contesto) {
    switch (ambiente) {
        case AMBIENTE_TEST:
            switch (contesto) {
                case SICI:
                    return configuration.siciSecretKeyTest();
                case ARET:
                    return configuration.aretSecretKeyTest();
                case HUB_PROCEDIMENTI:
                    return configuration.hubProcedimentiSecretKeyTest();
                default:
                    throw new RuntimeException();
            }
        case AMBIENTE_PRODUZIONE:
            switch (contesto) {
                case SICI:
                    return configuration.siciSecretKeyProd();
                case ARET:
                    return configuration.aretSecretKeyProd();
                case HUB_PROCEDIMENTI:
                    return configuration.hubProcedimentiSecretKeyProd();
                default:
                    throw new RuntimeException();
            }
        default:
            throw new RuntimeException();
    }
}

private String getConsumerKey(ApiPugliaEnteConfiguration configuration, AmbienteRiferimento ambiente, Contesto contesto) {
    switch (ambiente) {
        case AMBIENTE_TEST:
            switch (contesto) {
                case SICI:
                    return configuration.siciConsumerKeyTest();
                case ARET:
                    return configuration.aretConsumerKeyTest();
                case HUB_PROCEDIMENTI:
                    return configuration.hubProcedimentiConsumerKeyTest();
                default:
                    throw new RuntimeException();
            }
        case AMBIENTE_PRODUZIONE:
            switch (contesto) {
                case SICI:
                    return configuration.siciConsumerKeyProd();
                case ARET:
                    return configuration.aretConsumerKeyProd();
                case HUB_PROCEDIMENTI:
                    return configuration.hubProcedimentiConsumerKeyProd();
                default:
                    throw new RuntimeException();
            }
        default:
            throw new RuntimeException();
    }
}

private String toToken(String json) {
    String token = "";

    JsonObject jsonObject = new JsonParser().parse(json).getAsJsonObject();

    if (jsonObject.has("access_token")) {
        token = jsonObject.get("access_token").getAsString();
    }

    return token;
}

