package it.servizidigitali.common.fdr.client.rest.util;

import java.io.ByteArrayOutputStream;
import java.io.IOException;
import java.io.InputStream;
import java.io.OutputStream;
import java.math.BigInteger;
import java.nio.charset.StandardCharsets;
import java.security.SecureRandom;
import java.util.ArrayList;
import java.util.List;

/**
 * Builder per la costruzione di richieste HTTP multipart/form-data.
 * Genera il corpo della richiesta con boundary casuale e formattazione
 * conforme allo standard RFC 2046.
 *
 * <p>Utilizzato per l'invio di file e dati JSON al servizio di firma remota.</p>
 *
 * @author Servizi Digitali
 * @see MultiPartBody
 * @see MultiPartRecord
 */
public class MultiPartBodyBuilder {
    public static MultiPartBody build(List<MultiPartRecord> records) {
        ByteArrayOutputStream baos = new ByteArrayOutputStream();
        String boundary = new BigInteger(256, new SecureRandom()).toString();
        for (MultiPartRecord record : records) {
            writeBoundary(baos, boundary);
            writeContentDisposition(baos, record);

            if (record.getContentType() != null) {
                writeContentType(baos, record);
            } else {
                writeLine(baos);
            }

            writeLine(baos);

            writeContent(baos, record.getStream());
            writeLine(baos);
        }
        writeBoundaryEnd(baos, boundary);

        return new MultiPartBody(boundary, baos.toByteArray());
    }

    private static void writeBoundaryEnd(OutputStream stream, String boundary) {
        writeLine(stream, "--" + boundary + "--");
    }

    private static void writeContentDisposition(OutputStream stream, MultiPartRecord record) {
        List<String> tokens = new ArrayList<>();
        tokens.add("Content-Disposition: form-data");
        tokens.add("name=\"" + record.getPartName() + "\"");
        if (record.getFilename() != null) {
            tokens.add("filename=\"" + record.getFilename() + "\"");
        }

        String contentDisposition = String.join("; ", tokens);
        writeLine(stream, contentDisposition);
    }

    private static void writeContentType(OutputStream stream, MultiPartRecord record) {
        writeLine(stream, "Content-Type: " + record.getContentType());
    }

    private static void writeContent(OutputStream outputStream, InputStream inputStream) {
        try (inputStream) {
            inputStream.transferTo(outputStream);
        } catch (IOException e) {
            throw new RuntimeException(e);
        }
    }

    private static void writeBoundary(OutputStream stream, String boundary) {
        writeLine(stream, "--" + boundary);
    }

    private static void writeLine(OutputStream stream) {
        writeLine(stream, "");
    }

    private static void writeLine(OutputStream stream, String s) {
        try {
            String line = s + "\r\n";
            stream.write(line.getBytes(StandardCharsets.UTF_8));
        } catch (IOException e) {
            throw new RuntimeException(e);
        }
    }
}

