67	    private String ottieniToken(HttpClient httpClient) throws Exception {
68	        String url = TOKEN_URL + "?grant_type=client_credentials";
69	        String credentials = CONSUMER_KEY + ":" + SECRET_KEY;
70	        String basic = Base64.getEncoder().encodeToString(credentials.getBytes(StandardCharsets.UTF_8));
71	
72	        HttpRequest request = HttpRequest.newBuilder()
73	                .uri(new URI(url))
74	                .method("POST", HttpRequest.BodyPublishers.noBody())
75	                .header("Authorization", "Basic " + basic)
76	                .header("Content-Type", "application/x-www-form-urlencoded")
77	                .header("Accept", "application/json")
78	                .timeout(REQUEST_TIMEOUT)
79	                .build();
80	
81	        HttpResponse<String> response = httpClient.send(request, HttpResponse.BodyHandlers.ofString());
82	
83	        System.out.println("=== TOKEN - Status: " + response.statusCode() + " ===");
84	
85	        return estraiAccessToken(response.body());
86	    }
