88	    private HttpResponse<String> verificaDocumento(HttpClient httpClient, String accessToken, byte[] fileBytes)
89	            throws Exception {
90	
91	        String boundary = "----FdrVerificaTestBoundary" + System.nanoTime();
92	        byte[] body = buildMultipartFilePart(boundary, fileBytes);
93	
94	        HttpRequest request = HttpRequest.newBuilder()
95	                .uri(new URI(VERIFICA_URL))
96	                .method("POST", HttpRequest.BodyPublishers.ofByteArray(body))
97	                .header("Accept", "application/json")
98	                .header("Authorization", "Bearer " + accessToken)
99	                .header("Content-Type", "multipart/form-data; boundary=" + boundary)
100	                .timeout(REQUEST_TIMEOUT)
101	                .build();
102	
103	        return httpClient.send(request, HttpResponse.BodyHandlers.ofString());
104	    }
105	
106	    private byte[] buildMultipartFilePart(String boundary, byte[] fileBytes) throws Exception {
107	        String header = "--" + boundary + "\r\n"
108	                + "Content-Disposition: form-data; name=\"file\"; filename=\"" + RESOURCE_FILE.substring(1) + "\"\r\n"
109	                + "Content-Type: " + FILE_MIME + "\r\n\r\n";
110	        String footer = "\r\n--" + boundary + "--\r\n";
111	
112	        ByteArrayOutputStream out = new ByteArrayOutputStream();
113	        out.write(header.getBytes(StandardCharsets.UTF_8));
114	        out.write(fileBytes);
115	        out.write(footer.getBytes(StandardCharsets.UTF_8));
116	        return out.toByteArray();
117	    }
